type PublicListCatalogGeneratedDataStatus = Literal[
    "closed_from_native_catalog",
    "closed_from_generated_package",
    "blocked_missing_generated_list_catalog_fields",
]


@dataclass(frozen=True)
class PublicListCatalogGeneratedDataContract:
    package_path: str
    status: PublicListCatalogGeneratedDataStatus
    blocker_reason: str
    tag_lookup_table_count: int
    tag_lookup_lookup_tag_count: int
    tag_lookup_tag_exists_count: int
    tag_lookup_only_lowercase_name_count: int
    native_listx_table_count: int
    native_listx_tag_count: int
    native_available_tag_count: int
    required_generated_fields: tuple[str, ...]
    missing_generated_fields: tuple[str, ...]
    generated_data_contract: tuple[str, ...]
    evidence_ids: tuple[str, ...]


