def public_list_command_line_shortcuts() -> tuple[str, ...]:
    try:
        from exifmodern.public_interface.read_options import public_read_shortcut_names
    except ModuleNotFoundError:
        return tuple(sorted(_PUBLIC_LIST_FALLBACK_SHORTCUT_TARGETS, key=str.casefold))
    return public_read_shortcut_names()


def public_list_shortcut_targets(shortcut: str) -> tuple[str, ...] | None:
    try:
        from exifmodern.public_interface.read_options import public_read_shortcut_targets
    except ModuleNotFoundError:
        for fallback_shortcut, targets in _PUBLIC_LIST_FALLBACK_SHORTCUT_TARGETS.items():
            if fallback_shortcut.lower() == shortcut.lower():
                return targets
        return None
    return public_read_shortcut_targets(shortcut)


