def _with_canonical_duplicate_tables_last(
    tables: tuple[PublicListxTableInfo, ...],
) -> tuple[PublicListxTableInfo, ...]:
    canonical_table_names = (
        "EXIF::Main",
        "EXIF::ExifIFD",
        "GPS::Main",
        "IPTC::ApplicationRecord",
        "XMP::dc",
    )
    canonical_table_name_set = frozenset(canonical_table_names)
    canonical_tables_by_name = {
        table.name: table for table in tables if table.name in canonical_table_name_set
    }
    return (
        *(table for table in tables if table.name not in canonical_table_name_set),
        *(canonical_tables_by_name[name] for name in canonical_table_names),
    )


def _with_generated_exif_catalog_tags(
    tables: tuple[PublicListxTableInfo, ...],
) -> tuple[PublicListxTableInfo, ...]:
    return tuple(_with_generated_exif_table_tags(table) for table in tables)


def _with_generated_exif_table_tags(table: PublicListxTableInfo) -> PublicListxTableInfo:
    generated_tags = {
        "EXIF::Main": (*_GENERATED_EXIF_MAIN_TAGS, *_GENERATED_EXIF_IFD_FAMILY_TAGS),
        "EXIF::ExifIFD": _GENERATED_EXIF_EXIF_IFD_TAGS,
    }.get(table.name)
    if not generated_tags:
        return table
    existing_names = frozenset(tag.name for tag in table.tags)
    tags = (*table.tags, *(tag for tag in generated_tags if tag.name not in existing_names))
    return PublicListxTableInfo(
        name=table.name,
        group_0=table.group_0,
        group_1=table.group_1,
        group_2=table.group_2,
        description=table.description,
        tags=tags,
    )


