def public_list_available_tags() -> tuple[str, ...]:
    """Return the bounded public list catalog union in ExifTool list order."""
    return tuple(
        sorted(
            frozenset((*_PUBLIC_LIST_AVAILABLE_TAGS, *_public_listx_tag_names())),
            key=str.casefold,
        )
    )


def public_list_writable_tags() -> tuple[str, ...]:
    """Return writable names represented in the bounded public listx catalog."""
    writable_tags = (*_PUBLIC_LIST_WRITABLE_TAGS, *_public_listx_tag_names(writable_only=True))
    return tuple(
        sorted(
            frozenset(writable_tags),
            key=str.casefold,
        )
    )


def _public_listx_tag_names(*, writable_only: bool = False) -> frozenset[str]:
    return frozenset(
        tag.name
        for table in _PUBLIC_LISTX_TABLES
        for tag in table.tags
        if not writable_only or tag.writable
    )


def public_list_groups_by_family() -> dict[int, tuple[str, ...]]:
    groups_by_family = {
        family: set(groups) for family, groups in _PUBLIC_LIST_GROUPS_BY_FAMILY.items()
    }
    for table in _PUBLIC_LISTX_TABLES:
        groups_by_family.setdefault(0, set()).add(table.group_0)
        groups_by_family.setdefault(1, set()).add(table.group_1)
        groups_by_family.setdefault(2, set()).add(table.group_2)
        for tag in table.tags:
            if tag.group_0 is not None:
                groups_by_family[0].add(tag.group_0)
            if tag.group_1 is not None:
                groups_by_family[1].add(tag.group_1)
            if tag.group_2 is not None:
                groups_by_family[2].add(tag.group_2)
    return {
        family: tuple(sorted(groups, key=str.casefold))
        for family, groups in groups_by_family.items()
    }


def public_list_catalog() -> PublicListCatalog:
    package_catalog = generated_public_list_catalog_from_shards()
    if package_catalog is None:
        package_catalog = generated_public_list_catalog(generated_index_package_path())
    if package_catalog is not None:
        return package_catalog
    return PublicListCatalog(
        available_tags=public_list_available_tags(),
        command_line_shortcuts=_PUBLIC_LIST_COMMAND_LINE_SHORTCUTS,
        writable_tags=public_list_writable_tags(),
        supported_extensions=_PUBLIC_DIRECTORY_READ_EXTENSIONS,
        recognized_extensions=_PUBLIC_LIST_RECOGNIZED_EXTENSIONS,
        writable_extensions=_PUBLIC_LIST_WRITABLE_EXTENSIONS,
        extension_descriptions=_PUBLIC_LIST_EXTENSION_DESCRIPTIONS,
        deletable_groups=_PUBLIC_LIST_DELETABLE_GROUPS,
        groups_by_family=public_list_groups_by_family(),
        listx_tables=_PUBLIC_LISTX_TABLES,
        group_filter_display_names=_PUBLIC_LIST_GROUP_FILTER_DISPLAY_NAMES,
        shortcut_targets=_PUBLIC_LIST_SHORTCUT_TARGETS,
    )


def generated_public_list_catalog_from_shards() -> PublicListCatalog | None:
    listx_path = generated_index_shard_path("listx_catalog")
    file_type_path = generated_index_shard_path("file_type_catalog")
    group_family_path = generated_index_shard_path("group_family_catalog")
    if listx_path is None or file_type_path is None or group_family_path is None:
        return None
    return public_list_catalog_from_generated_data(
        listx_data=load_json_object(listx_path),
        file_type_data=load_json_object(file_type_path),
        group_family_data=load_json_object(group_family_path),
    )


@lru_cache(maxsize=4)
def generated_public_list_catalog(package_path: Path) -> PublicListCatalog | None:
    if not package_path.is_file():
        return None
    package = load_json_object(package_path)
    listx_data = generated_index_data(package, "listx_catalog")
    file_type_data = generated_index_data(package, "file_type_catalog")
    group_family_data = generated_index_data(package, "group_family_catalog")
    return public_list_catalog_from_generated_data(
        listx_data=listx_data,
        file_type_data=file_type_data,
        group_family_data=group_family_data,
    )


def public_list_catalog_from_generated_data(
    *,
    listx_data: JsonObject,
    file_type_data: JsonObject,
    group_family_data: JsonObject,
) -> PublicListCatalog | None:
    if not listx_data or not file_type_data or not group_family_data:
        return None
    listx_tables = merge_generated_static_listx_tables(generated_listx_tables(listx_data))
    if not listx_tables:
        return None
    supported_extensions, recognized_extensions, writable_extensions, descriptions = (
        generated_file_type_catalog(file_type_data)
    )
    groups_by_family = generated_group_family_catalog(group_family_data)
    return PublicListCatalog(
        available_tags=generated_public_tag_names(listx_tables, writable_only=False),
        command_line_shortcuts=_PUBLIC_LIST_COMMAND_LINE_SHORTCUTS,
        writable_tags=generated_public_tag_names(listx_tables, writable_only=True),
        supported_extensions=supported_extensions,
        recognized_extensions=recognized_extensions,
        writable_extensions=writable_extensions,
        extension_descriptions=descriptions,
        deletable_groups=_PUBLIC_LIST_DELETABLE_GROUPS,
        groups_by_family=groups_by_family,
        listx_tables=listx_tables,
        group_filter_display_names=_PUBLIC_LIST_GROUP_FILTER_DISPLAY_NAMES,
        shortcut_targets=_PUBLIC_LIST_SHORTCUT_TARGETS,
    )


def generated_index_data(package: JsonObject, kind: str) -> JsonObject:
    for index_value in json_array_value(package, "indexes"):
        if not isinstance(index_value, dict):
            continue
        if json_string_value(index_value, "kind") != kind:
            continue
        return json_object_items(index_value, "data")
    return {}


def generated_listx_tables(data: JsonObject) -> tuple[PublicListxTableInfo, ...]:
    tables: list[PublicListxTableInfo] = []
    for table_value in json_array_value(data, "tables"):
        if not isinstance(table_value, dict):
            continue
        table = generated_listx_table(table_value)
        if table is not None:
            tables.append(table)
    return tuple(tables)


def merge_generated_static_listx_tables(
    generated_tables: tuple[PublicListxTableInfo, ...],
) -> tuple[PublicListxTableInfo, ...]:
    generated_names = frozenset(table.name for table in generated_tables)
    static_only_tables = tuple(
        table for table in _PUBLIC_LISTX_TABLES if table.name not in generated_names
    )
    return (*generated_tables, *static_only_tables)


def generated_listx_table(value: JsonObject) -> PublicListxTableInfo | None:
    name = json_string_value(value, "name")
    group_0 = json_string_value(value, "g0")
    group_1 = json_string_value(value, "g1")
    group_2 = json_string_value(value, "g2")
    description = json_string_value(value, "description")
    if name is None or group_0 is None or group_1 is None or group_2 is None or description is None:
        return None
    tags = tuple(
        tag
        for tag_value in json_array_value(value, "tags")
        if isinstance(tag_value, dict)
        if (tag := generated_listx_tag(tag_value)) is not None
    )
    return PublicListxTableInfo(
        name=name,
        group_0=group_0,
        group_1=group_1,
        group_2=group_2,
        description=description,
        tags=tags,
        translated_descriptions=generated_translated_descriptions(value),
    )


def generated_listx_tag(value: JsonObject) -> PublicListxTagInfo | None:
    tag_id = json_string_value(value, "id")
    name = json_string_value(value, "name")
    value_type = json_string_value(value, "type")
    writable = json_bool_value(value, "writable")
    description = json_string_value(value, "description")
    if (
        tag_id is None
        or name is None
        or value_type is None
        or writable is None
        or description is None
    ):
        return None
    return PublicListxTagInfo(
        tag_id=tag_id,
        name=name,
        value_type=value_type,
        writable=writable,
        description=description,
        index=json_int_value(value, "index"),
        group_0=json_string_value(value, "g0"),
        group_1=json_string_value(value, "g1"),
        group_2=json_string_value(value, "g2"),
        count=json_string_value(value, "count"),
        struct=json_string_value(value, "struct"),
        flags=tuple(
            item
            for item_value in json_array_value(value, "flags")
            if isinstance(item_value, str)
            for item in (item_value,)
        ),
        values=generated_listx_values(value),
        translated_values=generated_translated_values(value),
        translated_descriptions=generated_translated_descriptions(value),
    )


def generated_translated_descriptions(value: JsonObject) -> tuple[tuple[str, str], ...]:
    pairs: list[tuple[str, str]] = []
    for description_value in json_array_value(value, "translated_descriptions"):
        if not isinstance(description_value, dict):
            continue
        language = json_string_value(description_value, "lang")
        text = json_string_value(description_value, "text")
        if language is not None and text is not None:
            pairs.append((language, text))
    return tuple(pairs)


def generated_listx_values(value: JsonObject) -> tuple[tuple[str, str], ...]:
    pairs: list[tuple[str, str]] = []
    for item_value in json_array_value(value, "values"):
        if not isinstance(item_value, dict):
            continue
        key_id = json_string_value(item_value, "id")
        text = json_string_value(item_value, "value")
        if key_id is not None and text is not None:
            pairs.append((key_id, text))
    return tuple(pairs)


def generated_translated_values(value: JsonObject) -> tuple[tuple[str, str, str], ...]:
    triples: list[tuple[str, str, str]] = []
    for item_value in json_array_value(value, "translated_values"):
        if not isinstance(item_value, dict):
            continue
        key_id = json_string_value(item_value, "id")
        language = json_string_value(item_value, "lang")
        text = json_string_value(item_value, "value")
        if key_id is not None and language is not None and text is not None:
            triples.append((key_id, language, text))
    return tuple(triples)


def generated_file_type_catalog(
    data: JsonObject,
) -> tuple[frozenset[str], frozenset[str], frozenset[str], dict[str, str]]:
    supported: set[str] = set()
    recognized: set[str] = set()
    writable: set[str] = set()
    descriptions: dict[str, str] = {}
    for extension_value in json_array_value(data, "extensions"):
        if not isinstance(extension_value, dict):
            continue
        extension = json_string_value(extension_value, "extension")
        if extension is None:
            continue
        dotted = f".{extension.lower()}"
        if json_bool_value(extension_value, "supported"):
            supported.add(dotted)
        if json_bool_value(extension_value, "recognized"):
            recognized.add(dotted)
        if json_bool_value(extension_value, "writable"):
            writable.add(dotted)
        description = json_string_value(extension_value, "description")
        if description is not None:
            descriptions[extension.upper()] = description
    return frozenset(supported), frozenset(recognized), frozenset(writable), descriptions


def generated_group_family_catalog(data: JsonObject) -> dict[int, tuple[str, ...]]:
    groups_by_family: dict[int, tuple[str, ...]] = {}
    for family_value in json_array_value(data, "families"):
        if not isinstance(family_value, dict):
            continue
        family = json_int_value(family_value, "family")
        if family is None:
            continue
        groups = tuple(
            group_value
            for group_value in json_array_value(family_value, "groups")
            if isinstance(group_value, str)
        )
        groups_by_family[family] = groups
    return groups_by_family


def generated_public_tag_names(
    tables: tuple[PublicListxTableInfo, ...],
    *,
    writable_only: bool,
) -> tuple[str, ...]:
    names: list[str] = []
    seen: set[str] = set()
    for table in tables:
        for tag in table.tags:
            if writable_only and not tag.writable:
                continue
            if tag.name in seen:
                continue
            names.append(tag.name)
            seen.add(tag.name)
    return tuple(sorted(names, key=str.casefold))


def public_list_catalog_generated_data_contract(
    package_path: Path,
    *,
    catalog: PublicListCatalog | None = None,
) -> PublicListCatalogGeneratedDataContract:
    """Classify whether generated package data can close full public list parity."""
    resolved_catalog = catalog if catalog is not None else public_list_catalog()
    repository = load_tag_lookup_repository(package_path)
    package = load_json_object(package_path) if package_path.is_file() else {}
    has_generated_contract_indexes = all(
        generated_index_data(package, kind)
        for kind in ("listx_catalog", "file_type_catalog", "group_family_catalog")
    )
    native_tag_names = frozenset(
        tag.name.lower() for table in resolved_catalog.listx_tables for tag in table.tags
    )
    native_available_names = frozenset(tag.lower() for tag in resolved_catalog.available_tags)
    generated_tag_names = repository.tag_exists | frozenset(repository.lookup)
    tag_lookup_only_names = generated_tag_names - native_tag_names - native_available_names
    missing_fields = _missing_public_list_catalog_generated_fields(
        repository_has_data=repository.has_data,
        has_generated_contract_indexes=has_generated_contract_indexes,
    )
    if missing_fields or (tag_lookup_only_names and not has_generated_contract_indexes):
        status: PublicListCatalogGeneratedDataStatus = (
            "blocked_missing_generated_list_catalog_fields"
        )
    elif has_generated_contract_indexes:
        status = "closed_from_generated_package"
    else:
        status = "closed_from_native_catalog"
    blocker_reason = (
        "The local TagLookup generated-index package is consumed and proves broad "
        "source tag-name/table-id coverage, but it does not contain the listx, "
        "file-type, or group-family fields required to replace ExifTool "
        "TagInfoXML::Write/GetFileType/GetAllGroups output."
        if status == "blocked_missing_generated_list_catalog_fields"
        else "Native public catalog and generated package expose all fields required by this contract."
    )
    return PublicListCatalogGeneratedDataContract(
        package_path=str(package_path),
        status=status,
        blocker_reason=blocker_reason,
        tag_lookup_table_count=len(repository.table_list),
        tag_lookup_lookup_tag_count=len(repository.lookup),
        tag_lookup_tag_exists_count=len(repository.tag_exists),
        tag_lookup_only_lowercase_name_count=len(tag_lookup_only_names),
        native_listx_table_count=len(resolved_catalog.listx_tables),
        native_listx_tag_count=sum(len(table.tags) for table in resolved_catalog.listx_tables),
        native_available_tag_count=len(resolved_catalog.available_tags),
        required_generated_fields=_PUBLIC_LIST_CATALOG_REQUIRED_GENERATED_FIELDS,
        missing_generated_fields=missing_fields,
        generated_data_contract=_PUBLIC_LIST_CATALOG_GENERATED_DATA_CONTRACT,
        evidence_ids=_PUBLIC_LIST_CATALOG_SOURCE_EVIDENCE,
    )


def _missing_public_list_catalog_generated_fields(
    *,
    repository_has_data: bool,
    has_generated_contract_indexes: bool,
) -> tuple[str, ...]:
    if has_generated_contract_indexes:
        return ()
    if not repository_has_data:
        return _PUBLIC_LIST_CATALOG_REQUIRED_GENERATED_FIELDS
    return tuple(
        field
        for field in _PUBLIC_LIST_CATALOG_REQUIRED_GENERATED_FIELDS
        if field not in _PUBLIC_LIST_CATALOG_TAG_LOOKUP_AVAILABLE_FIELDS
    )


def public_list_catalog_generated_data_contract_to_json_value(
    contract: PublicListCatalogGeneratedDataContract,
    *,
    include_evidence: bool = False,
) -> JsonObject:
    payload: JsonObject = {
        "artifact_kind": "batch217_lane_a_public_list_catalog_generated_data_contract",
        "package_path": contract.package_path,
        "status": contract.status,
        "blocker_reason": contract.blocker_reason,
        "tag_lookup": {
            "table_count": contract.tag_lookup_table_count,
            "lookup_tag_count": contract.tag_lookup_lookup_tag_count,
            "tag_exists_count": contract.tag_lookup_tag_exists_count,
            "tag_lookup_only_lowercase_name_count": contract.tag_lookup_only_lowercase_name_count,
        },
        "native_public_catalog": {
            "listx_table_count": contract.native_listx_table_count,
            "listx_tag_count": contract.native_listx_tag_count,
            "available_tag_count": contract.native_available_tag_count,
        },
        "required_generated_fields": list(contract.required_generated_fields),
        "missing_generated_fields": list(contract.missing_generated_fields),
        "generated_data_contract": list(contract.generated_data_contract),
    }
    if include_evidence:
        payload[PUBLIC_EVIDENCE_JSON_KEY] = list(public_evidence_values(contract.evidence_ids))
    return payload


def write_public_list_catalog_generated_data_contract(
    contract: PublicListCatalogGeneratedDataContract,
    output_path: Path,
) -> None:
    payload: JsonValue = public_list_catalog_generated_data_contract_to_json_value(contract)
    output_path.write_text(
        json.dumps(payload, indent=2, sort_keys=True, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )
